document.querySelectorAll('.pg').forEach(nav => {
  const pages = [...nav.querySelectorAll('a:not([aria-label])')];
  const prev = nav.querySelector('[aria-label="Previous page"]'), next = nav.querySelector('[aria-label="Next page"]');
  const show = i => {
    i = Math.max(0, Math.min(pages.length - 1, i));
    pages.forEach((a, k) => k === i ? a.setAttribute('aria-current', 'page') : a.removeAttribute('aria-current'));
    prev.setAttribute('aria-disabled', String(i === 0)); next.setAttribute('aria-disabled', String(i === pages.length - 1));
  };
  const cur = () => pages.findIndex(a => a.getAttribute('aria-current') === 'page');
  nav.addEventListener('click', e => {
    const a = e.target.closest('a'); if (!a) return;
    e.preventDefault(); /* demo only */
    if (a === prev) show(cur() - 1); else if (a === next) show(cur() + 1); else show(pages.indexOf(a));
  });
  show(cur());
});
